import sys
import os
import site

# print debug messages when $EBPYTHONPREFIXES_DEBUG is defined
debug = os.getenv('EBPYTHONPREFIXES_DEBUG')



# The priority of paths is as followed:
# EBPYTHONPREFIXES_PRIORITY
# core python functions (part of the language)
# python modules installed in virtual environments
# EBPYTHONPREFIXES
# python modules installed in the python module

ebpythonprefixes = os.getenv('EBPYTHONPREFIXES')
ebpythonprefixes_priority = os.getenv('EBPYTHONPREFIXES_PRIORITY')
virtualenv = os.getenv('VIRTUAL_ENV')

postfix = os.path.join('lib', 'python' + '.'.join(map(str, sys.version_info[:2])), 'site-packages')
if debug:
    print("[EBPYTHONPREFIXES] post subdirectory to consider in installation directories: %s" % postfix)


def addsitedir(sitedir, location=None):
    current_path = list(sys.path) # sys.path.copy()
    if debug:
        print("[EBPYTHONPREFIXES] processing %s" % sitedir)
    site.addsitedir(sitedir)
    diff_path = [x for x in sys.path if x not in current_path]
    if debug:
        print("[EBPYTHONPREFIXES] paths added by addsitedir: %s" % diff_path)

    if location is not None:
        if debug:
            print("[EBPYTHONPREFIXES] inserting into location %s" % location)
        sys.path = current_path
        for path in reversed(diff_path):
            sys.path.insert(location, path)
        if debug:
            print("[EBPYTHONPREFIXES] resulting sys.path %s" % sys.path)


if ebpythonprefixes_priority:
    for prefix in ebpythonprefixes_priority.split(os.pathsep):
        if debug:
            print("[EBPYTHONPREFIXES] prefix: %s" % prefix)

        sitedir = os.path.join(prefix, postfix)
        if os.path.isdir(sitedir):
            addsitedir(sitedir, 0)

if ebpythonprefixes:
    for prefix in ebpythonprefixes.split(os.pathsep):
        if debug:
            print("[EBPYTHONPREFIXES] prefix: %s" % prefix)
        sitedir = os.path.join(prefix, postfix)
        if os.path.isdir(sitedir):
            # use prefixes from EBPYTHONPREFIXES, so they have lower priority than
            # virtualenv-installed packages
            if virtualenv or "/cvmfs/soft.computecanada.ca/easybuild/software" not in sys.executable:
                addsitedir(sitedir)
            # if it is not a virtualenv, we should actually add the prefix before the root python dir
            # because the module may be trying to overwrite python modules installed in the base python
            else:
                addsitedir(sitedir,-1)

if debug:
    print("[EBYPTHONPREFIXES] resulting sitedir: %s" % "\n".join(sys.path))



# Append site-packages in Nix profile to sys.path so packages can be found there.
# This avoids needing to set PYTHONPATH to this directory.
# virtualenv uses a private site-packages directory so this should NOT be done inside
# a virtualenv; in that case
# /cvmfs/soft.computecanada.ca/nix/store/<hash>/lib/pythonx.y/site-packages
# is not in sys.path either

def get_base_prefix():
    """Get base prefix, valid for virtualenv, pyvenv, and python without virtualenv"""
    return getattr(sys, 'real_prefix', getattr(sys, 'base_prefix', sys.prefix))

if get_base_prefix().startswith('/cvmfs/soft.computecanada.ca/nix/store/'):
    newprefix = os.environ.get("EBROOTPYTHON")
    if newprefix is not None:
        postfix = os.path.join('lib', 'python' + '.'.join(map(str, sys.version_info[:2])), 'site-packages')
        nixstoresitepackages = os.path.join(sys.prefix, postfix)
        if nixstoresitepackages in sys.path:
            site.addsitedir(os.path.join(newprefix, postfix))

OS_CERT_PATHS = [
    "/etc/ssl/certs/ca-certificates.crt",                  # Debian/Ubuntu/Gentoo
    "/etc/pki/tls/certs/ca-bundle.crt",                    # Fedora/RHEL 6/CentOS
    "/etc/pki/ca-trust/extracted/pem/tls-ca-bundle.pem",   # Fedora/RHEL 7+
    "/etc/ssl/cert.pem",                                   # macOS/Alpine/OpenSUSE/FreeBSD
    "/var/lib/ca-certificates/ca-bundle.pem"               # SLES
]

def _is_newer(path_a, path_b):
    """Return True if path_a is strictly newer than path_b (by mtime), False otherwise."""
    try:
        return os.path.getmtime(path_a) > os.path.getmtime(path_b)
    except Exception:
        return False

def _read_file(filepath):
    """Read file content safely across Python 2 and 3."""
    try:
        with open(filepath, 'r', errors='ignore') if sys.version_info[0] >= 3 else open(filepath, 'r') as f:
            return f.read()
    except Exception:
        return ''


def _is_force_system_cert():
    """Return True if FORCE_SYSTEM_CERT is set to 1/truthy or points to a valid file."""
    val = os.environ.get("FORCE_SYSTEM_CERT")
    if not val:
        return False
    if val in ['1', 'true', 'TRUE', 'yes', 'YES']:
        return True
    if os.path.isfile(val):
        return True
    return False

def get_system_cert_path():
    # If FORCE_SYSTEM_CERT points to a file, use it directly
    force_val = os.environ.get("FORCE_SYSTEM_CERT")
    if force_val and force_val != '1' and os.path.isfile(force_val):
        return os.path.abspath(force_val)

    # Check if an environment variable overrides it first
    for env_var in ["SSL_CERT_FILE", "REQUESTS_CA_BUNDLE", "CURL_CA_BUNDLE"]:
        val = os.environ.get(env_var)
        if val and os.path.isfile(val):
            return os.path.abspath(val)

    # Try the path Python's ssl module was compiled against (most reliable cross-platform)
    try:
        import ssl
        cafile = ssl.get_default_verify_paths().cafile
        if cafile and os.path.isfile(cafile):
            return cafile
    except Exception:
        pass

    # Fallback to scanning common OS paths
    for path in OS_CERT_PATHS:
        if os.path.exists(path):
            return path
    return None

def parse_version(version_str):
    if not version_str:
        return ()
    import re
    parts = []
    for part in re.split(r'[-._]', str(version_str)):
        m = re.match(r'^\d+', part)
        if m:
            parts.append(int(m.group(0)))
        else:
            break
    return tuple(parts)

try:
    import certifi

    # Safe version boundary that removed the vulnerable eMudhra certificates
    SAFE_VERSION = (2026, 10, 19)
    current_version = parse_version(getattr(certifi, '__version__', '0.0.0'))
    if debug:
        print("[EBPYTHONPREFIXES] certifi version: %s" % (current_version,))
    force_system_cert = _is_force_system_cert()
    if force_system_cert or current_version < SAFE_VERSION:
        # If FORCE_SYSTEM_CERT=1 is defined, unconditionally inject the system certificate.
        # Otherwise, only replace it if certifi is older/vulnerable and the OS bundle is newer.
        pkg_cert = certifi.where()
        system_cert = get_system_cert_path()
        if debug:
            print("[EBPYTHONPREFIXES] certifi pkg cert: %s, system_cert: %s (force=%s)" % (pkg_cert, system_cert, force_system_cert))
        if system_cert and (force_system_cert or _is_newer(system_cert, pkg_cert)):
            if debug:
                print("[EBPYTHONPREFIXES] certifi: injecting %s (force=%s)" % (system_cert, force_system_cert))
            # Inject host OS store paths
            certifi.where = lambda: system_cert

            if hasattr(certifi, 'contents'):
                certifi.contents = lambda: _read_file(system_cert)
        elif debug:
            print("[EBPYTHONPREFIXES] certifi: OS bundle is not newer than pkg bundle, skipping injection")
    else:
        # certifi >= 2026.10.19 is already patched. Do nothing and use its internal bundle.
        pass

except ImportError:
    if debug:
        print("[EBPYTHONPREFIXES] certifi not imported")
    # Handle environments where certifi isn't present during early initialization
    pass

# Inject the OS certificate bundle into pip's vendored certifi when pip is old
# or when FORCE_SYSTEM_CERT=1 is defined.
# pip always loads its own vendored certifi IN ADDITION to the system trust store,
# and there is no supported way to disable this. Patching pip._vendor.certifi.where()
# redirects all of pip's HTTPS connections to the OS bundle.
try:
    import pip._vendor.certifi as pip_certifi

    PIP_SAFE_VERSION = (26, 2, 2)
    try:
        import pip as _pip_mod
        pip_version = getattr(_pip_mod, '__version__', None)
    except ImportError:
        pip_version = None

    force_system_cert = _is_force_system_cert()
    if force_system_cert or (pip_version and parse_version(pip_version) < PIP_SAFE_VERSION):
        system_cert = get_system_cert_path()
        pkg_cert = pip_certifi.where()
        if debug:
            print("[EBPYTHONPREFIXES] pip vendored certifi: pkg cert %s, system cert %s (pip %s < %s, force=%s)"
                  % (pkg_cert, system_cert, pip_version, PIP_SAFE_VERSION, force_system_cert))
        if system_cert and (force_system_cert or _is_newer(system_cert, pkg_cert)):
            if debug:
                print("[EBPYTHONPREFIXES] pip vendored certifi: injecting %s (force=%s)" % (system_cert, force_system_cert))
            pip_certifi.where = lambda: system_cert
            if hasattr(pip_certifi, 'contents'):
                pip_certifi.contents = lambda: _read_file(system_cert)
        elif debug:
            print("[EBPYTHONPREFIXES] pip vendored certifi: OS bundle is not newer, skipping injection")
    else:
        if debug:
            print("[EBPYTHONPREFIXES] pip vendored certifi: version %s is safe, no injection needed" % pip_version)

except ImportError:
    if debug:
        print("[EBPYTHONPREFIXES] pip._vendor.certifi not importable")
    pass
except Exception as e:
    if debug:
        print("[EBPYTHONPREFIXES] error injecting pip vendored certifi: %s" % e)

# When FORCE_SYSTEM_CERT=1 is requested, also export SSL_CERT_FILE and REQUESTS_CA_BUNDLE
# so standard library ssl and other HTTP libraries (requests, urllib3) respect the forced bundle.
if _is_force_system_cert():
    system_cert = get_system_cert_path()
    if system_cert:
        os.environ['SSL_CERT_FILE'] = system_cert
        os.environ['REQUESTS_CA_BUNDLE'] = system_cert
        if debug:
            print("[EBPYTHONPREFIXES] FORCE_SYSTEM_CERT active: exported SSL_CERT_FILE and REQUESTS_CA_BUNDLE as %s" % system_cert)

# Check for presence of compromised eMudhra / Comodo CA certificates
def _get_pkg_version(pkg_name):
    try:
        from importlib.metadata import version
        return version(pkg_name)
    except Exception:
        pass
    try:
        import pkg_resources
        return pkg_resources.get_distribution(pkg_name).version
    except Exception:
        pass
    try:
        import importlib
        mod = importlib.import_module(pkg_name)
        return getattr(mod, '__version__', None)
    except Exception:
        pass
    return None


def _check_emudhra_in_pem_file(filepath):
    content = _read_file(filepath)
    if not content:
        return False
    # 1. eMudhra / emSign: Only the G3 hierarchy (e.g. emSign ECC Root CA - G3,
    #    emSign Root TLS CA - G3, and their subordinate CAs) suffered from compromised
    #    private keys. emSign Root CA - G1 is an unaffected RSA root and remains valid.
    # 2. Comodo: The "AAA Certificate Services" root (Comodo CA Limited) cross-signed
    #    the compromised eMudhra intermediates and is untrusted per RHSB-2026-012.
    if '-----begin certificate-----' in content.lower():
        import base64
        for block in content.split('-----END CERTIFICATE-----'):
            if '-----BEGIN CERTIFICATE-----' in block:
                block_lower = block.lower()
                # Check comments/plaintext metadata associated with this certificate
                if ('emudhra' in block_lower or 'emsign' in block_lower) and ('- g3' in block_lower or 'ca - g3' in block_lower or 'root cs ca' in block_lower):
                    return True
                if 'aaa certificate services' in block_lower and 'comodo' in block_lower:
                    return True
                if 'comodo aaa services root' in block_lower:
                    return True
                # Check the base64-decoded DER representation of this certificate
                try:
                    b64 = block.split('-----BEGIN CERTIFICATE-----')[-1]
                    b64 = ''.join([
                        line.strip() for line in b64.splitlines()
                        if line.strip() and not line.startswith('#') and not line.startswith('-')
                    ])
                    der = base64.b64decode(b64).lower()
                    if (b'emudhra' in der or b'emsign' in der) and b'g3' in der:
                        return True
                    if b'aaa certificate services' in der and b'comodo' in der:
                        return True
                except Exception:
                    pass
    return False


def _check_emudhra_in_json_file(filepath):
    content = _read_file(filepath)
    if not content:
        return False
    lower = content.lower()
    if 'rawbytes' in lower or 'certificateauthorities' in lower:
        import json, base64
        try:
            data = json.loads(content)
            for ca in data.get('certificateAuthorities', []):
                for cert in ca.get('certChain', {}).get('certificates', []):
                    raw = base64.b64decode(cert.get('rawBytes', '')).lower()
                    if (b'emudhra' in raw or b'emsign' in raw) and b'g3' in raw:
                        return True
                    if b'aaa certificate services' in raw and b'comodo' in raw:
                        return True
        except Exception:
            pass
    return False


def _find_pip_cert_path():
    # Check pip._vendor.certifi.where() first: this respects any injection we did above.
    try:
        import pip._vendor.certifi as pip_certifi
        ca = pip_certifi.where()
        if ca and os.path.isfile(ca):
            if debug:
                print("[EBPYTHONPREFIXES] pip._vendor.certifi.where(): %s" % ca)
            return ca
    except Exception:
        pass
    # Fallback: find the bundled cacert.pem on disk directly
    try:
        import importlib.util
        spec = importlib.util.find_spec('pip')
        if spec and spec.submodule_search_locations:
            for loc in spec.submodule_search_locations:
                ca = os.path.join(loc, '_vendor', 'certifi', 'cacert.pem')
                if os.path.isfile(ca):
                    return ca
    except Exception:
        pass
    return None


def _find_certifi_cert_path():
    try:
        import certifi
        ca = certifi.where()
        if debug:
            print("[EBPYTHONPREFIXES] certifi CA found: %s" % ca)
        if os.path.isfile(ca):
            return ca
    except Exception:
        pass
    try:
        import importlib.util
        spec = importlib.util.find_spec('certifi')
        if spec and spec.submodule_search_locations:
            for loc in spec.submodule_search_locations:
                ca = os.path.join(loc, 'cacert.pem')
                if os.path.isfile(ca):
                    return ca
    except Exception:
        pass
    return None


def _find_sigstore_cert_path():
    try:
        import importlib.util
        spec = importlib.util.find_spec('sigstore')
        if spec and spec.submodule_search_locations:
            for loc in spec.submodule_search_locations:
                for root, dirs, files in os.walk(loc):
                    for fname in files:
                        fpath = os.path.join(root, fname)
                        if fname.endswith(('.pem', '.crt')) and _check_emudhra_in_pem_file(fpath):
                            return fpath
                        elif fname.endswith('.json') and _check_emudhra_in_json_file(fpath):
                            return fpath
    except Exception:
        pass
    user_cache = os.path.expanduser('~/.cache/sigstore')
    if os.path.isdir(user_cache):
        for root, dirs, files in os.walk(user_cache):
            for fname in files:
                fpath = os.path.join(root, fname)
                if fname.endswith(('.pem', '.crt')) and _check_emudhra_in_pem_file(fpath):
                    return fpath
                elif fname.endswith('.json') and _check_emudhra_in_json_file(fpath):
                    return fpath
    return None


def _warn_emudhra_detected(detections):
    is_tty = hasattr(sys.stderr, 'isatty') and sys.stderr.isatty()
    RED = '\033[91m' if is_tty else ''
    YELLOW = '\033[93m' if is_tty else ''
    BOLD = '\033[1m' if is_tty else ''
    RESET = '\033[0m' if is_tty else ''

    border = '=' * 74
    lines = [
        "",
        "%s%s%s%s" % (RED, BOLD, border, RESET),
        "%s%sSECURITY WARNING: Compromised CA Certificate Detected!%s" % (RED, BOLD, RESET),
        "%sA compromised eMudhra/emSign or Comodo (AAA Certificate Services) root%s" % (YELLOW, RESET),
        "%sCertificate Authority (CA) certificate was detected in your Python environment:%s" % (YELLOW, RESET),
    ]
    for det in detections:
        pkg = det['package']
        ver = det['version']
        cpath = det['cert_path']
        if ver == 'custom bundle':
            lines.append("  - %s%s%s (%s)" % (BOLD, pkg, RESET, cpath))
            lines.append("    %sAction needed:%s Update or remove this certificate bundle." % (BOLD, RESET))
        else:
            lines.append("  - %s%s%s (installed version: %s)" % (BOLD, pkg, RESET, ver))
            lines.append("    Certificate path: %s" % cpath)
            lines.append("    %sAction needed:%s Upgrade %s by running:" % (BOLD, RESET, pkg))
            lines.append("        %spython -m pip install --upgrade %s%s" % (BOLD, pkg, RESET))

    lines.extend([
        "",
        "%sDue to critically weak private keys or cross-signed trust paths (RHSB-2026-012),%s" % (YELLOW, RESET),
        "%sthese certificates expose TLS/HTTPS connections to Man-in-the-Middle (MITM) attacks%s" % (YELLOW, RESET),
        "%s(e.g. against PyPI). Please upgrade the affected package(s) or configure a clean%s" % (YELLOW, RESET),
        "%ssystem certificate bundle (e.g. by setting FORCE_SYSTEM_CERT=1).%s" % (YELLOW, RESET),
        "%s%s%s%s" % (RED, BOLD, border, RESET),
        ""
    ])
    try:
        sys.stderr.write("\n".join(lines) + "\n")
        sys.stderr.flush()
    except Exception:
        pass


def check_emudhra_certificates():
    if os.getenv('SILENCE_EMUDHRA_WARNING') or os.getenv('IGNORE_EMUDHRA_WARNING') or os.getenv('SILENCE_CA_WARNING'):
        return

    targets = [
        ('pip', (26, 2, 2), _find_pip_cert_path),
        ('certifi', (2026, 10, 19), _find_certifi_cert_path),
        ('sigstore', (4, 5, 1), _find_sigstore_cert_path),
    ]

    detections = []
    for pkg_name, min_ver, find_cert_fn in targets:
        ver = _get_pkg_version(pkg_name)
        if debug:
            print("[EBPYTHONPREFIXES] checking %s: detected version %s, required >= %s" % (pkg_name, ver, min_ver))
        if not ver:
            continue
        parsed_ver = parse_version(ver)
        # Abort early if the package version is recent enough to be safe
        if parsed_ver >= min_ver:
            continue

        # Insecure/older version: check if the certificate in use is actually compromised.
        # Do not alert just because the version is old.
        cert_path = find_cert_fn()
        if debug:
            print("[EBPYTHONPREFIXES] %s is older version (%s < %s), cert path: %s" % (pkg_name, ver, min_ver, cert_path))
        if cert_path:
            if cert_path.endswith('.json'):
                has_cert = _check_emudhra_in_json_file(cert_path)
            else:
                has_cert = _check_emudhra_in_pem_file(cert_path)
            if has_cert:
                detections.append({
                    'package': pkg_name,
                    'version': ver,
                    'cert_path': cert_path,
                })

    # Also check explicitly configured environment bundles or local cacert.pem in the current working directory
    custom_bundles = []
    for env_var in ['SSL_CERT_FILE', 'REQUESTS_CA_BUNDLE', 'CURL_CA_BUNDLE']:
        val = os.environ.get(env_var)
        if val and os.path.isfile(val):
            custom_bundles.append((env_var, os.path.abspath(val)))

    for fname in ['cacert.pem', 'ca-bundle.crt']:
        cwd_cert = os.path.abspath(fname)
        if os.path.isfile(cwd_cert):
            custom_bundles.append(('current directory bundle (%s)' % fname, cwd_cert))

    for source_name, bpath in custom_bundles:
        if _check_emudhra_in_pem_file(bpath):
            if not any(d['cert_path'] == bpath for d in detections):
                detections.append({
                    'package': source_name,
                    'version': 'custom bundle',
                    'cert_path': bpath,
                })

    if detections:
        _warn_emudhra_detected(detections)


try:
    check_emudhra_certificates()
except Exception as e:
    if debug:
        print("[EBPYTHONPREFIXES] error checking for eMudhra certificates: %s" % e)
